      details: { perPath: outcomes },
    }) as BindingResult;
  }
  if (outcomes.some((item) => item.outcome.status === 'CYCLE_DETECTED')) {
    return deepFreeze({
      eligible: false,
      code: 'CYCLE_DETECTED',
      details: { perPath: outcomes },
    }) as BindingResult;
  }
  if (outcomes.some((item) => item.outcome.status === 'CONTESTED')) {
    return deepFreeze({
      eligible: false,
      kind: 'CONTESTED',
      details: { perPath: outcomes },
    }) as BindingResult;
  }
  return deepFreeze({
    eligible: false,
    code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
    details: { perPath: outcomes },
  }) as BindingResult;
}

